import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function ProveidorsList() {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');

  useEffect(() => {
    const fetchClients = async () => {
      try {
        setLoading(true);
        setError(null);

        const res = await fetch('http://localhost/api/clients', {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error('Error al obtenir els clients');

        const data = await res.json();
        setClients(data.dades || []);
      } catch (err) {
        console.error(err);
        setError('Error al obtenir els clients');
      } finally {
        setLoading(false);
      }
    };

    fetchClients();
  }, [token]);

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (clients.length === 0) {
    return <p className="mt-3">No hi ha clients disponibles</p>;
  }


}

export default ProveidorsList;
